using System.Data;
using Microsoft.EntityFrameworkCore;
using Saldo360.Application.Goals;
using Saldo360.Domain.Accounts;
using Saldo360.Domain.Categories;
using Saldo360.Domain.Goals;
using Saldo360.Infrastructure.Persistence;
namespace Saldo360.Infrastructure.Goals;
internal sealed class FinancialGoalAllocationRepository(Saldo360DbContext db) : IFinancialGoalAllocationRepository
{
 public Task<FinancialGoalAllocationDto?> GetByOperationAsync(Guid f,Guid op,CancellationToken ct)=>Project(db.FinancialGoalAllocations.Where(x=>x.FamilyId==f&&x.OperationId==op)).SingleOrDefaultAsync(ct);
 public async Task<bool> PayloadMatchesAsync(Guid f,Guid op,Guid goal,Guid account,FinancialGoalAllocationType type,decimal amount,DateOnly date,string? description,CancellationToken ct){var x=await db.FinancialGoalAllocations.AsNoTracking().SingleAsync(x=>x.FamilyId==f&&x.OperationId==op,ct);return x.GoalId==goal&&x.FinancialAccountId==account&&x.OperationType==type&&x.Amount==amount&&x.EffectiveDate==date&&x.Description==(string.IsNullOrWhiteSpace(description)?null:description.Trim());}
 public async Task<GoalAllocationResult> TryCreateAsync(FinancialGoalAllocation a,decimal target,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var account=await db.FinancialAccounts.SingleOrDefaultAsync(x=>x.FamilyId==a.FamilyId&&x.Id==a.FinancialAccountId,ct);if(account is null)return new(GoalAllocationAccess.NotFound,null,null);if(!account.IsActive)return new(GoalAllocationAccess.Conflict,null,null,"A conta está inativa.");var opening=account.OpeningBalance; if(opening is null||account.OpeningBalanceDate is null)return new(GoalAllocationAccess.Conflict,null,null,"A conta não possui saldo inicial configurado.");var txTotals=await db.FinancialTransactions.Where(x=>x.FamilyId==a.FamilyId&&x.AccountId==a.FinancialAccountId&&!x.IsCancelled&&x.TransactionDate>=account.OpeningBalanceDate&&x.TransactionDate<=a.EffectiveDate).GroupBy(x=>x.AccountId).Select(g=>new{Income=g.Sum(x=>x.Type==CategoryType.Income?x.Amount:0m),Expense=g.Sum(x=>x.Type==CategoryType.Expense?x.Amount:0m)}).SingleOrDefaultAsync(ct);var transfers=await db.FinancialTransfers.Where(x=>x.FamilyId==a.FamilyId&&!x.IsCancelled&&x.TransferDate>=account.OpeningBalanceDate&&x.TransferDate<=a.EffectiveDate&&(x.SourceAccountId==a.FinancialAccountId||x.DestinationAccountId==a.FinancialAccountId)).GroupBy(x=>x.FamilyId).Select(g=>new{In=g.Sum(x=>x.DestinationAccountId==a.FinancialAccountId?x.Amount:0m),Out=g.Sum(x=>x.SourceAccountId==a.FinancialAccountId?x.Amount:0m)}).SingleOrDefaultAsync(ct);var realized=opening.Value+(txTotals?.Income??0m)-(txTotals?.Expense??0m)+(transfers?.In??0m)-(transfers?.Out??0m);var allocated=await db.FinancialGoalAllocations.Where(x=>x.FamilyId==a.FamilyId&&x.FinancialAccountId==a.FinancialAccountId&&x.CancelledAt==null).SumAsync(x=>x.OperationType==FinancialGoalAllocationType.Contribution?x.Amount:-x.Amount,ct);var available=realized-allocated;var delta=a.OperationType==FinancialGoalAllocationType.Contribution?a.Amount:-a.Amount;if(available<0||available+delta<0)return new(GoalAllocationAccess.Conflict,null,null,"Saldo não alocado insuficiente.");var goalAllocated=await db.FinancialGoalAllocations.Where(x=>x.FamilyId==a.FamilyId&&x.GoalId==a.GoalId&&x.CancelledAt==null).SumAsync(x=>x.OperationType==FinancialGoalAllocationType.Contribution?x.Amount:-x.Amount,ct);if(a.OperationType==FinancialGoalAllocationType.Contribution&&goalAllocated+a.Amount>target)return new(GoalAllocationAccess.Conflict,null,null,"O aporte supera o valor-alvo.");db.FinancialGoalAllocations.Add(a);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return new(GoalAllocationAccess.Allowed,await GetByOperationAsync(a.FamilyId,a.OperationId,ct),null);}catch(DbUpdateException){await tx.RollbackAsync(ct);return new(GoalAllocationAccess.Conflict,null,null,"A operação entrou em conflito com outra alocação.");}}
 public async Task<IReadOnlyList<FinancialGoalAllocationDto>> ListAsync(Guid f,Guid g,CancellationToken ct)=>await Project(db.FinancialGoalAllocations.AsNoTracking().Where(x=>x.FamilyId==f&&x.GoalId==g).OrderBy(x=>x.EffectiveDate).ThenBy(x=>x.CreatedAt)).ToListAsync(ct);
 public Task<FinancialGoalAllocation?> FindAsync(Guid f,Guid g,Guid id,CancellationToken ct)=>db.FinancialGoalAllocations.SingleOrDefaultAsync(x=>x.FamilyId==f&&x.GoalId==g&&x.Id==id,ct);
 public async Task<GoalProgressDto?> ProgressAsync(Guid f,Guid g,decimal target,CancellationToken ct){var amount=await db.FinancialGoalAllocations.Where(x=>x.FamilyId==f&&x.GoalId==g&&x.CancelledAt==null).SumAsync(x=>x.OperationType==FinancialGoalAllocationType.Contribution?x.Amount:-x.Amount,ct);var remaining=Math.Max(0m,target-amount);return new(g,target,amount,remaining,target==0?0:amount/target*100,amount>=target);}
 public Task<GoalAccountAvailabilityDto?> AvailabilityAsync(Guid f,Guid accountId,CancellationToken ct)=>AvailabilityCore(f,accountId,ct);
 public async Task<IReadOnlyList<GoalAccountAvailabilityDto>> ListAccountsAvailabilityAsync(Guid f,CancellationToken ct){var ids=await db.FinancialAccounts.AsNoTracking().Where(x=>x.FamilyId==f).Select(x=>x.Id).ToListAsync(ct);var list=new List<GoalAccountAvailabilityDto>();foreach(var id in ids)if(await AvailabilityCore(f,id,ct) is{ } x)list.Add(x);return list;}
 private async Task<GoalAccountAvailabilityDto?> AvailabilityCore(Guid f,Guid id,CancellationToken ct){var a=await db.FinancialAccounts.AsNoTracking().SingleOrDefaultAsync(x=>x.FamilyId==f&&x.Id==id,ct);if(a is null||a.OpeningBalance is null||a.OpeningBalanceDate is null)return null;var today=DateOnly.FromDateTime(DateTime.UtcNow);var t=await db.FinancialTransactions.Where(x=>x.FamilyId==f&&x.AccountId==id&&!x.IsCancelled&&x.TransactionDate>=a.OpeningBalanceDate&&x.TransactionDate<=today).GroupBy(x=>x.AccountId).Select(g=>new{I=g.Sum(x=>x.Type==CategoryType.Income?x.Amount:0m),E=g.Sum(x=>x.Type==CategoryType.Expense?x.Amount:0m)}).SingleOrDefaultAsync(ct);var tr=await db.FinancialTransfers.Where(x=>x.FamilyId==f&&!x.IsCancelled&&x.TransferDate>=a.OpeningBalanceDate&&x.TransferDate<=today&&(x.SourceAccountId==id||x.DestinationAccountId==id)).GroupBy(x=>x.FamilyId).Select(g=>new{I=g.Sum(x=>x.DestinationAccountId==id?x.Amount:0m),O=g.Sum(x=>x.SourceAccountId==id?x.Amount:0m)}).SingleOrDefaultAsync(ct);var realized=a.OpeningBalance.Value+(t?.I??0m)-(t?.E??0m)+(tr?.I??0m)-(tr?.O??0m);var allocated=await db.FinancialGoalAllocations.Where(x=>x.FamilyId==f&&x.FinancialAccountId==id&&x.CancelledAt==null).SumAsync(x=>x.OperationType==FinancialGoalAllocationType.Contribution?x.Amount:-x.Amount,ct);return new(id,realized,allocated,realized-allocated);}
 public Task SaveAsync(CancellationToken ct)=>db.SaveChangesAsync(ct);
 private static IQueryable<FinancialGoalAllocationDto> Project(IQueryable<FinancialGoalAllocation> q)=>q.Select(x=>new FinancialGoalAllocationDto(x.Id,x.FamilyId,x.GoalId,x.FinancialAccountId,x.OperationType,x.Amount,x.EffectiveDate,x.OperationId,x.Description,x.CreatedAt,x.CancelledAt));
}
